  "anomalies": [
    {
      "category": "wrong_value",
      "components": ["C3"],
      "pins": ["C3.1", "C3.2"],
      "nets": ["Net-(D2-K)", "GND"],
      "observed": "C3 is specified with value \"100m\" in the netlist and SPICE deck, unlike C1, C2, C4 which are \"100u\".",
      "expected": "C3 should be 100u (100 µF) as one of the four 100 µF bulk capacitors C1–C4 on the servo power rail.",
      "evidence": [
        {
          "source": "spec",
          "quote": "C1–C4 | 100 µF × 4 | Bulk capacitance on the servo power rail (downstream of D2), buffering the high inrush current of PWM servos."
        },
        {
          "source": "netlist",
          "quote": "(comp (ref \"C3\") (value \"100m\")"
        },
        {
          "source": "spice",
          "quote": "C3 Net-_D2-K_ 0 100m"
        }
      ],
      "impact": "One servo-rail bulk capacitor becomes 100 mF (0.1 F), 1000× the intended 100 µF. This would drastically change inrush/charging behavior, make the specified 1206 footprint physically impossible for the value, and cause the board to behave differently from the intended design.",
      "confidence": 0.99
    }
  ],
  "summary": "The design files contain one anomaly: C3 is specified as 100m instead of 100u, making one of the four 100 µF servo-rail bulk capacitors 1000× too large."
}

